// A throwaway consumer app, generated by tools/verify-consumer/android.sh (after the release, from
// Maven Central) or android-bundle.sh (before the upload, from the unzipped bundle) outside the
// repository. It is deliberately NOT a composite build of android/: the point is to resolve the SDK
// the way a customer's app does, so a missing artefact, a POM that names a module that was never
// uploaded, or a metadata mismatch fails here.
pluginManagement {
    repositories {
        google()
        mavenCentral()
        gradlePluginPortal()
    }
}

dependencyResolutionManagement {
    repositoriesMode.set(RepositoriesMode.FAIL_ON_PROJECT_REPOS)
    // The scripts fill in the repositories: android.sh gives exactly the two the README tells an
    // integrator to have (google() and mavenCentral(); adding mavenLocal(), a snapshot repository
    // or the Sonatype staging URL would let a broken release pass), android-bundle.sh adds the
    // bundle as the only source of io.versola.
    repositories {
__REPOSITORIES__
    }
}

rootProject.name = "verify-consumer"
include(":app")
